// ***************
// Filename: gpio_regs.h
// Author: FPGA Cores 4 U
// Description: C header of the gpio register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-20
#ifndef GPIO_REGS_H
#define GPIO_REGS_H
#define GPIO_REGS_ID_OFFSET 0x00u
#define GPIO_REGS_VERSION_OFFSET 0x04u
#define GPIO_REGS_DATE_OFFSET 0x08u
#define GPIO_REGS_ID_VALUE 0x4750494Fu   /* "GPIO" */
#define GPIO_REGS_OUT_OFFSET 0x10u   /* CMD */
#define GPIO_REGS_OUT_RESET 0x00000000u
#define GPIO_REGS_DIR_OFFSET 0x14u   /* RW */
#define GPIO_REGS_DIR_RESET 0x00000000u
#define GPIO_REGS_IN_OFFSET 0x18u   /* RO */
#define GPIO_REGS_IN_RESET 0x00000000u
#define GPIO_REGS_SET_OFFSET 0x1Cu   /* WO */
#define GPIO_REGS_SET_RESET 0x00000000u
#define GPIO_REGS_CLEAR_OFFSET 0x20u   /* WO */
#define GPIO_REGS_CLEAR_RESET 0x00000000u
#define GPIO_REGS_TOGGLE_OFFSET 0x24u   /* WO */
#define GPIO_REGS_TOGGLE_RESET 0x00000000u
#define GPIO_REGS_INT_EN_OFFSET 0x28u   /* RW */
#define GPIO_REGS_INT_EN_RESET 0x00000000u
#define GPIO_REGS_RISE_EN_OFFSET 0x2Cu   /* RW */
#define GPIO_REGS_RISE_EN_RESET 0x00000000u
#define GPIO_REGS_FALL_EN_OFFSET 0x30u   /* RW */
#define GPIO_REGS_FALL_EN_RESET 0x00000000u
#define GPIO_REGS_INT_STATUS_OFFSET 0x34u   /* W1C */
#define GPIO_REGS_INT_STATUS_RESET 0x00000000u
#endif /* GPIO_REGS_H */
